style.css:
@-moz-document domain("roblox.com") {
:root {
    --kids-background: #07164f;
    --kids-sidebar: #07164f;
    --kids-header: #07164f;
    --kids-search: #14285f;
    --kids-avatar: #1b306d;
    --kids-text: #f7f8ff;
    --kids-online: #20c997;
  }

  /* MAIN BACKGROUND */
  html,
  body,
  #container-main,
  .container-main,
  .content,
  .home-container,
  .game-home-page-container {
    background-color: var(--kids-background) !important;
    color: var(--kids-text) !important;
  }

  /* TOP NAVIGATION */
  .rbx-header,
  .navbar,
  header,
  .header {
    background: var(--kids-header) !important;
    border: none !important;
    box-shadow: none !important;
  }

  /* LEFT SIDEBAR */
  .rbx-left-col,
  .left-col,
  .left-navigation,
  .navigation,
  .navbar-fixed-left {
    background: var(--kids-sidebar) !important;
    border: none !important;
    color: white !important;
  }

  .rbx-left-col a,
  .left-col a,
  .navigation a {
    color: #f2f4ff !important;
  }

  /* SEARCH BAR */
  .navbar-search,
  .search-container,
  input[type="search"],
  input[type="text"] {
    background: var(--kids-search) !important;
    color: white !important;
    border: 1px solid #1c3270 !important;
    border-radius: 13px !important;
  }

  input::placeholder {
    color: #d5ddf4 !important;
  }

  /* PAGE HEADINGS */
  h1, h2, h3, h4,
  .section-title,
  .container-header {
    color: white !important;
    font-weight: 700 !important;
  }

  /* FRIENDS */
  .friend-carousel,
  .friend-carousel-container,
  .friends-container,
  .avatar-card-container {
    color: white !important;
  }

  .avatar-card,
  .avatar-card-container img,
  .friend-avatar {
    border-radius: 50% !important;
  }

  /* GAME RECOMMENDATIONS */
  .game-card,
  .game-card-container,
  .game-tile,
  .list-item {
    color: white !important;
  }

  .game-card-thumb-container,
  .game-card img,
  .game-tile img {
    border-radius: 11px !important;
  }

  /* GAME TITLES */
  .game-card-name,
  .game-name,
  .game-title {
    color: white !important;
  }

  /* PROFILE STATUS */
  .profile-name,
  .avatar-name,
  .text-name {
    color: white !important;
  }

  /* BUTTONS */
  button,
  .btn-control,
  .btn-secondary-md {
    border-radius: 12px !important;
  }

  /* ONLINE STATUS */
  .icon-online,
  .avatar-status {
    background-color: var(--kids-online) !important;
  }

  /* SCROLLBAR */
  ::-webkit-scrollbar {
    width: 9px;
  }

  ::-webkit-scrollbar-track {
    background: #07164f;
  }

  ::-webkit-scrollbar-thumb {
    background: #6476a8;
    border-radius: 20px;
  }
}
